import math
from itertools import combinations

def quartic_direction(point):
    gradient = point**3-point
    curvature = 3*point**2-1
    if gradient == 0:
        return 0., 'stationary'
    if curvature > 0:
        return -gradient/curvature, 'newton'
    return -gradient, 'gradient_fallback'

def solve(point):
    return quartic_direction(point)

